47	        String key = this.householdKey.of(lastName, address);
48	        return "HH-" + sha256(key).substring(0, 12).toUpperCase(Locale.ROOT);
49	    }
50	
51	    private static String sha256(String value) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                .digest(value.getBytes(StandardCharsets.UTF_8));
55	            StringBuilder hex = new StringBuilder(digest.length * 2);
56	            for (byte b : digest) {
57	                hex.append(String.format("%02x", b));
58	            }
59	            return hex.toString();
60	        }
61	        catch (NoSuchAlgorithmException ex) {
62	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
63	        }
64	    }
65	}
